{
  "name": "opencode-vision",
  "version": "0.2.1",
  "description": "OpenCode v2 plugin for video: record_screen (Windows screen/window capture), video_frames (labelled contact sheets any image model can read) and watch_video (native video model).",
  "type": "module",
  "license": "MIT",
  "author": "KelpHect",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/KelpHect/opencode-vision.git"
  },
  "homepage": "https://github.com/KelpHect/opencode-vision#readme",
  "bugs": {
    "url": "https://github.com/KelpHect/opencode-vision/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "video",
    "screen-recording",
    "vision",
    "ffmpeg"
  ],
  "main": "index.ts",
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "src",
    "skills",
    "LICENSE",
    "README.md"
  ],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.30",
    "@types/bun": "1.4.3",
    "typescript": "5.9.3"
  }
}
